        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int l = scanner.nextInt() - 1;
        int r = scanner.nextInt() - 1;
        int totalLength = a + b;
        int diff = r - l;
        int result;
        if (diff >= 2 * totalLength) {
