    static int findDifferenceCount(int a, int b, int l, int r) {
        int first = b < a ? b : a - 1;
        int last = a - 1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a; i++) {
            sb.append((char) ('a' + i));
        }
        char ch = l < a ? sb.charAt(last) : sb.charAt(first);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        boolean[] usedLetters = new boolean[30];
        for (int i = 0; i < a; i++) {
            usedLetters[sb.charAt(sb.length() - i - 1) - 'a'] = true;
        }
