            sb.append((char) ('a' + ptr));
            usedLetters[ptr] = true;
        }
        ch = sb.charAt(Math.min(b, a - 1) + a + b);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        for (int i = 0; i < a + b; i++) {
            sb.append(sb.charAt(i));
        }
        return countDistinctLetters(sb.toString(), l, r);
    }

    static int countDistinctLetters(String s, int l, int r) {
        boolean[] used = new boolean[30];
        for (int i = l; i <= r; i++) {
            used[s.charAt(i) - 'a'] = true;
        }
        int count = 0;
        for (boolean b : used) {
            if (b) count++;
        }
        return count;
    }
