#include <bits/stdc++.h>
using namespace std;

int findDifferenceCount(int a, int b, int l, int r);
int countDistinctLetters(const std::string& s, int l, int r);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    int totalLength = a + b;
    int diff = r - l;
    int result;
    if (diff >= 2 * totalLength) {
        result = max(a + 1, 2 * a - b);
    } else {
        r -= totalLength * (l / totalLength);
        l %= totalLength;
        result = findDifferenceCount(a, b, l, r);
    }
    cout << result << "\n";
    return 0;
}

int findDifferenceCount(int a, int b, int l, int r) {
    int first = b < a ? b : a - 1;
    int last = a - 1;
    std::string sb;
    for (int i = 0; i < a; i++) {
        sb.push_back('a' + i);
    }
    char ch = (l < a) ? sb.at(last) : sb.at(first);
    for (int i = 0; i < b; i++) {
        sb.push_back(ch);
    }
    std::vector<bool> usedLetters(30, false);
    for (int i = 0; i < a; i++) {
        usedLetters[sb[sb.size() - i - 1] - 'a'] = true;
    }
    int ptr = 0;
    for (int i = 0; i < a; i++) {
        while (usedLetters[ptr]) ptr++;
        sb.push_back('a' + ptr);
        usedLetters[ptr] = true;
    }
    ch = sb.at(std::min(b, a - 1) + a + b);
    for (int i = 0; i < b; i++) {
        sb.push_back(ch);
    }
    for (int i = 0; i < a + b; i++) {
        sb.push_back(sb[i]);
    }
    return countDistinctLetters(sb, l, r);
}

int countDistinctLetters(const std::string& s, int l, int r) {
    std::vector<bool> used(30, false);
    for (int i = l; i <= r; i++) {
        used[s[i] - 'a'] = true;
    }
    int count = 0;
    for (bool b : used) {
        if (b) count++;
    }
    return count;
}

